import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long a = scanner.nextLong();
        long b = scanner.nextLong();
        long n = scanner.nextLong();
        long minDiff = 1000000000L;
        long finalX = 0;
        long finalY = 1;
        for (long y = 1; y <= n; y++) {
            long xGuess = (a * y) / b;
            for (int offset = -5; offset <= 5; offset++) {
                long candidateX = xGuess + offset;
                long diffValue = Math.abs(b * candidateX - a * y);
                if (diffValue * 1000000000L < minDiff * b * y) {
                    minDiff = diffValue;
                    finalX = candidateX;
                    finalY = y;
                }
            }
        }
        System.out.println(finalX + "/" + finalY);
        scanner.close();
    }
}
